def latest_health(rows):
    latest={}
    for r in sorted(rows,key=lambda r:r['run_id']):latest[(r['build_id'],r['test_id'])]=r
    selected=list(latest.values());total=len(selected);failed=sum(r['status']=='failed' for r in selected)
    return {'total':total,'failed':failed,'pass_rate':(total-failed)/total if total else 0}

